mapper.select:
SELECT * FROM message_failure


    consumer_group = #{consumerGroup}


ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM message_inbox
WHERE processed_at < #{cutoff}
  AND NOT EXISTS (
    SELECT 1 FROM business_outbox o
    WHERE o.id = message_inbox.event_id AND o.state <> 'DONE'
  )

mapper.delete:
DELETE FROM message_inbox
WHERE processed_at < #{cutoff}
  AND NOT EXISTS (
    SELECT 1 FROM business_outbox o
    WHERE o.id = message_inbox.event_id AND o.state <> 'DONE'
  )
ORDER BY consumer_group, event_id
LIMIT #{limit}

mapper.select:
SELECT COUNT(*) FROM message_failure
WHERE created_at < #{cutoff}
  AND (event_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM business_outbox o
    WHERE o.id = message_failure.event_id AND o.state = 'REVIEW'
  ))

mapper.delete:
DELETE FROM message_failure
WHERE created_at < #{cutoff}
  AND (event_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM business_outbox o
    WHERE o.id = message_failure.event_id AND o.state = 'REVIEW'
  ))
ORDER BY created_at, consumer_group, event_key
LIMIT #{limit}
